 totalimetvsh = 0;
}

private void xrLabel48_SummaryGetResult(object sender, DevExpress.XtraReports.UI.SummaryGetResultEventArgs e) {
  e.Result = totalimetvsh - Convert.ToDouble(GetCurrentColumnValue("ZBRITJE")); 
            e.Handled = true;
}
private void label10_SummaryRowChanged(object sender, System.EventArgs e) {
  totVec += Convert.ToDouble(GetCurrentColumnValue("VLEFTAMETVSH"));
}

private void label10_SummaryReset(object sender, System.EventArgs e) {
 totVec = 0;
}

private void label10_SummaryGetResult(object sender, DevExpress.XtraReports.UI.SummaryGetResultEventArgs e) {
double kursi = Convert.ToDouble(GetCurrentColumnValue("KURSI"));
double tot= totVec - Convert.ToDouble(GetCurrentColumnValue("ZBRITJE"));
  e.Result = tot*kursi; 
            e.Handled = true;
}


private void xrLabel52_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
